(()=>{'use strict';const $=s=>document.querySelector(s),message=$('#message');let role='child',busy=false;
// Retire old offline copies: every new navigation must pass server authentication.
if('serviceWorker'in navigator)navigator.serviceWorker.getRegistrations().then(rs=>rs.forEach(r=>r.unregister()));
if('caches'in window)caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('future-compass-')).map(k=>caches.delete(k))));
async function api(path,data){const r=await fetch(path,{method:data?'POST':'GET',cache:'no-store',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const v=await r.json();if(!r.ok)throw Error(v.error||'잠시 후 다시 시도해 주세요.');return v}
async function action(form,fn){if(busy)return;busy=true;const buttons=[...document.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);message.textContent='확인하고 있어요…';try{await fn()}catch(e){message.textContent=e.message||'연결을 확인해 주세요.'}finally{busy=false;buttons.forEach(b=>b.disabled=false)}}
if($('#login-form')){function change(r){role=r;const child=r==='child';$('#child-tab').setAttribute('aria-pressed',child);$('#admin-tab').setAttribute('aria-pressed',!child);$('#title').textContent=child?'승준아, 반가워 🐾':'보호자 로그인 🔑';$('#intro').textContent=child?'우리의 비밀 번호 4자리를 눌러줘.':'보호자 비밀번호로 번호를 관리해요.';$('#password-label').textContent=child?'비밀 번호 4자리':'보호자 비밀번호';const p=$('#password');p.value='';p.inputMode=child?'numeric':'text';p.minLength=child?4:12;p.maxLength=child?4:128;if(child)p.pattern='[0-9]{4}';else p.removeAttribute('pattern');$('#remember-row').hidden=!child;$('#remember-row').style.display=child?'flex':'none';$('#submit').textContent=child?'아지트 들어가기 →':'보호자 관리 열기 →';$('#help').hidden=true;message.textContent='';p.focus()}
$('#child-tab').onclick=()=>change('child');$('#admin-tab').onclick=()=>change('admin');if(location.hash==='#parent')change('admin');
$('#forgot').onclick=()=>{$('#help').hidden=!$('#help').hidden;if(role==='admin')$('#help').textContent='보호자 비밀번호도 잊었다면 서버 소유자가 VPS 복구 명령으로 새로 설정할 수 있어요. 공부 기록은 유지됩니다.';else $('#help').textContent='괜찮아! 보호자가 ‘보호자’로 로그인한 다음 새 번호를 정해줄 수 있어. 공부 기록은 지워지지 않아.'};
$('#login-form').onsubmit=e=>{e.preventDefault();action(e.target,async()=>{const v=await api('/api/auth/login',{role,password:$('#password').value,remember:$('#remember').checked});$('#password').value='';location.replace(v.role==='admin'?'/parent.html':'/')})};$('#password').oninput=()=>{if(role==='child'){$('#password').value=$('#password').value.replace(/[^0-9]/g,'').slice(0,4);if($('#password').value.length===4&&!busy)$('#login-form').requestSubmit()}};
api('/api/auth/status').then(s=>{if(!s.configured){message.textContent='보호자의 첫 설정을 기다리고 있어요. 설정이 끝나면 사용할 수 있어요.';$('#submit').disabled=true}else if(s.role && !(s.role==='child' && location.hash==='#parent'))location.replace(s.role==='admin'?'/parent.html':'/')}).catch(()=>message.textContent='연결을 확인한 뒤 새로고침해 주세요.');
}else{api('/api/auth/status').then(s=>{if(s.role!=='admin')location.replace('/login.html#parent')}).catch(()=>message.textContent='연결을 확인해 주세요.');$('#reset-form').onsubmit=e=>{e.preventDefault();action(e.target,async()=>{if($('#pin').value!==$('#pin-again').value)throw Error('새 번호가 서로 달라요. 다시 확인해 주세요.');if(!confirm('새 PIN으로 변경하고 승준이의 모든 기기를 잠글까요? 공부 기록은 유지돼요.')){message.textContent='취소했어요.';return}await api('/api/auth/admin/reset-pin',{pin:$('#pin').value});e.target.reset();message.textContent='새 번호로 바꿨어요. 승준이에게 새 PIN을 알려주세요. 공부 기록은 그대로예요.'})};$('#lock-all').onclick=()=>action(null,async()=>{if(!confirm('승준이의 모든 기기를 잠글까요?')){message.textContent='취소했어요.';return}await api('/api/auth/admin/lock',{});message.textContent='모든 기기를 잠갔어요. 다시 로그인하면 이용할 수 있어요.'});$('#admin-password-form').onsubmit=e=>{e.preventDefault();action(e.target,async()=>{if($('#new-password').value!==$('#new-again').value)throw Error('새 비밀번호가 서로 달라요.');await api('/api/auth/admin/password',{current:$('#current').value,password:$('#new-password').value});alert('변경했어요. 새 보호자 비밀번호로 다시 로그인해 주세요.');location.replace('/login.html#parent')})};$('#logout').onclick=()=>action(null,async()=>{await api('/api/auth/logout',{});location.replace('/login.html')});}
})();
